import{_ as e,o,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD Weekly 2020-11-04","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD Weekly 2020-11-04","date":"2020-11-04T00:00:00.000Z","updated":"2020-11-17T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","消息编码","复制","快照","克隆","虚拟化","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-11-04.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-11-04.md","lastUpdated":1780460162000}'),t={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-11-04.md"};function s(a,l,n,p,g,d){return o(),i("div",null,[...l[0]||(l[0]=[r('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ol><li><p><strong>对象上下文锁定恢复问题</strong>：</p><ul><li>讨论了PG活动集更改时解锁对象上下文的问题。</li><li>提出了使用<code>with lock</code>原语确保解锁操作总是被调用的解决方案。</li></ul></li><li><p><strong>EIO处理</strong>：</p><ul><li>讨论了在PG后端处理EIO（输入/输出错误）的适当位置。</li><li>决定将EIO处理移至<code>pg.cc</code>，并在客户端请求中处理重启逻辑。</li></ul></li><li><p><strong>PG状态修复</strong>：</p><ul><li>讨论了遇到EIO时将PG状态设置为修复的原因和后果。</li><li>确认修复状态是为了触发后续的scrub和修复操作。</li></ul></li><li><p><strong>文档编写</strong>：</p><ul><li>建议编写文档以解释设计目标和计划的上传位置，以帮助评审人员理解。</li></ul></li><li><p><strong>性能测试</strong>：</p><ul><li>讨论了将新功能添加到性能测试中的可能性，以确保代码路径的持续优化。</li></ul></li><li><p><strong>集合树的需求</strong>：</p><ul><li>讨论了是否需要为Ceph存储节点信息创建单独的树。</li><li>提出了使用现有接口和对象存储来处理集合信息的建议。</li></ul></li><li><p><strong>线程池处理</strong>：</p><ul><li>讨论了线程池处理和心跳计时器的使用，以防止长时间操作导致的心跳问题。</li></ul></li><li><p><strong>测试和分布式问题</strong>：</p><ul><li>讨论了测试的覆盖范围和特定分布的限制。</li></ul></li><li><p><strong>事务管理器和性能</strong>：</p><ul><li>讨论了事务管理器的性能测试和需要修复的问题。</li></ul></li><li><p><strong>Messenger更改</strong>：</p><ul><li>讨论了Messenger在多核环境下的运行问题和可能的设计变更。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><strong>EIO处理位置</strong>：决定将EIO处理逻辑移至<code>pg.cc</code>。</li><li><strong>文档编写</strong>：决定编写详细的设计文档来解释EIO处理的设计和实现。</li><li><strong>集合树的需求</strong>：决定不创建单独的树，而是使用现有接口来处理集合信息。</li><li><strong>Messenger更改</strong>：决定进一步研究Messenger在多核环境下的运行问题，并考虑设计变更。</li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><strong>编写设计文档</strong>：编写详细的设计文档，包括EIO处理和Messenger更改的设计。</li><li><strong>性能测试</strong>：将新功能添加到性能测试中，以确保代码路径的持续优化。</li><li><strong>集合树的研究</strong>：进一步研究集合树的需求和现有接口的使用。</li><li><strong>Messenger更改的研究</strong>：进一步研究Messenger在多核环境下的运行问题，并考虑设计变更。</li></ol><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议主要讨论了Ceph存储系统中的多个关键问题，包括EIO处理、对象上下文锁定恢复、集合树的需求和Messenger的更改。通过详细的讨论和决策，确定了后续的行动计划，以确保系统的稳定性和性能优化。</p>',10)])])}const c=e(t,[["render",s]]);export{u as __pageData,c as default};
